window.docContents[15].resolve({"/Gamma-Function/___5___5-Functional-Relations/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___5-Functional-Relations--___5___5_LPAR_iv_RPAR_-Bohr--Mollerup-Theorem":{"contents":"Source: DLMF §5.5(iv).\n\nIf f(x)>0 for x>0, f(x+1)=xf(x), f(1)=1, and \\ln f is convex on\n(0,\\infty), then\nf(x)=\\Gamma(x)\\qquad(x>0).The Bohr--Mollerup theorem characterizes the real Gamma function uniquely among positive,\nlog-convex functions satisfying the normalized recurrence. The conclusion is equality on the\npositive real axis; the values of f outside that interval are irrelevant.\n\n","context":"LMLF · DLMF with Lean\u0009Gamma Function\u0009§5.5 Functional Relations","header":"§5.5(iv) Bohr--Mollerup Theorem","id":"/Gamma-Function/___5___5-Functional-Relations/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___5-Functional-Relations--___5___5_LPAR_iv_RPAR_-Bohr--Mollerup-Theorem"}});